public class SlidingWindowPatterns {

    // ===== 固定窗口：大小为 k 的子数组最大平均值 =====
    // 思路：维护窗口和，每步 right 加入、left 移出，O(1) 更新
    public static double findMaxAverage(int[] nums, int k) {
        double sum = 0;
        for (int i = 0; i < k; i++) sum += nums[i]; // 初始窗口
        double maxSum = sum;
        for (int i = k; i < nums.length; i++) {
            sum += nums[i] - nums[i - k]; // O(1)：加入右端、移出左端
            maxSum = Math.max(maxSum, sum);
        }
        return maxSum / k;
    }

    // ===== 可变窗口（求最长）：最长无重复字符子串 =====
    // 答案在合法时更新（while 之外）
    public static int lengthOfLongestSubstring(String s) {
        int[] freq = new int[128]; // ASCII 字符计数
        int left = 0, maxLen = 0;
        for (int right = 0; right < s.length(); right++) {
            freq[s.charAt(right)]++;
            // 窗口非法：出现重复字符，收缩 left
            while (freq[s.charAt(right)] > 1) {
                freq[s.charAt(left)]--;
                left++;
            }
            // 窗口合法，更新最长长度
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }

    // ===== 可变窗口（求最短）：最小覆盖子串 =====
    // 答案在合法时更新（while 之内），收缩尝试找更短
    public static String minWindow(String s, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++; // 目标需求
        int satisfied = 0; // 已满足需求的字符种类数
        for (int i = 0; i < 128; i++) if (need[i] > 0) satisfied--; // 初始全部未满足
        // satisfied == 0 表示所有种类都满足

        int left = 0, minLen = Integer.MAX_VALUE, start = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            need[c]--;
            if (need[c] == 0) satisfied++; // 该字符需求恰好满足

            // 窗口合法（satisfied == 0），收缩找最短
            while (satisfied == 0) {
                if (right - left + 1 < minLen) { // while 内更新答案
                    minLen = right - left + 1;
                    start = left;
                }
                char lc = s.charAt(left);
                if (need[lc] == 0) satisfied--; // 移出后该字符不再满足
                need[lc]++;
                left++;
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
    }

    // ===== 可变窗口（求最短）：长度最小的子数组（和 ≥ target） =====
    public static int minSubArrayLen(int target, int[] nums) {
        int left = 0, sum = 0, minLen = Integer.MAX_VALUE;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (sum >= target) { // 合法时收缩
                minLen = Math.min(minLen, right - left + 1);
                sum -= nums[left++];
            }
        }
        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }
}
